CREATE TABLE IF NOT EXISTS membership_types (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,fee DECIMAL(12,2) NOT NULL DEFAULT 0,validity VARCHAR(100) NOT NULL,description TEXT NULL,is_active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
ALTER TABLE members ADD COLUMN membership_type_id BIGINT UNSIGNED NULL, ADD CONSTRAINT fk_member_membership_type FOREIGN KEY (membership_type_id) REFERENCES membership_types(id) ON DELETE SET NULL;
